@aware([
    'listboxId' => null,
    'size' => null,
])

@php
    $contentClasses = collect([
        'select__content',
        'z-[200] max-h-60 min-w-[8rem] overflow-y-auto overflow-x-hidden rounded-md border border-zinc-200 bg-white p-1 shadow-lg ring-1 ring-zinc-950/5',
        'focus:outline-none',
        'dark:border-zinc-800 dark:bg-zinc-950 dark:ring-white/10',
        $size === 'sm' ? 'text-sm' : null,
    ])->filter()->implode(' ');

    $contentAttributes = $attributes
        ->class($contentClasses)
        ->merge([
            'role' => 'listbox',
            'tabindex' => '-1',
            'data-select-content' => true,
            'hidden' => true,
        ]);

    if (filled($listboxId)) {
        $contentAttributes = $contentAttributes->merge(['id' => $listboxId]);
    }
@endphp

<div {{ $contentAttributes }}>
    {{ $slot }}
</div>

@props([
    'name' => null,
    'value' => null,
    'placeholder' => null,
    'size' => null,
    'invalid' => false,
    'disabled' => false,
    'selectId' => null,
    'listboxId' => null,
    'shortcut' => true,
])

@php
    $selectId = filled($selectId)
        ? $selectId
        : 'select-'.str_replace('.', '', uniqid('', true));
    $listboxId = filled($listboxId) ? $listboxId : $selectId.'-listbox';

    $wrapperClasses = collect([
        'select',
        'relative w-full min-w-0',
        $attributes->get('class'),
    ])->filter()->implode(' ');
@endphp

<div
    {{ $attributes->except(['class', 'shortcut'])->class($wrapperClasses) }}
    data-select
    data-select-id="{{ $selectId }}"
>
    @if (filled($name))
        <input
            type="hidden"
            name="{{ $name }}"
            value="{{ $value }}"
            data-select-hidden-input
        />
    @else
        <input
            type="hidden"
            value="{{ $value }}"
            data-select-hidden-input
        />
    @endif

    @if ($shortcut)
        <x-bladex-components::select.trigger>
            <x-bladex-components::select.value :placeholder="$placeholder" />
        </x-bladex-components::select.trigger>

        <x-bladex-components::select.content>
            {{ $slot }}
        </x-bladex-components::select.content>
    @else
        {{ $slot }}
    @endif
</div>

@props([
    'value' => null,
    'disabled' => false,
])

@aware([
    'size' => null,
])

@php
    $itemClasses = collect([
        'select__item',
        'relative flex w-full cursor-default select-none items-center gap-2 rounded-sm py-1.5 pl-2 pr-8 text-sm outline-none',
        'text-zinc-950 dark:text-zinc-50',
        'data-[highlighted]:bg-zinc-100 data-[highlighted]:text-zinc-900',
        'dark:data-[highlighted]:bg-zinc-800 dark:data-[highlighted]:text-zinc-50',
        'data-[disabled]:pointer-events-none data-[disabled]:opacity-50',
        'aria-selected:font-medium',
        '[&[aria-selected=true]_[data-select-item-check]]:opacity-100',
        $size === 'sm' ? 'py-1 text-xs' : null,
    ])->filter()->implode(' ');

    $itemAttributes = $attributes
        ->class($itemClasses)
        ->merge([
            'role' => 'option',
            'data-select-item' => true,
            'aria-selected' => 'false',
            'tabindex' => '-1',
        ]);

    if (filled($value)) {
        $itemAttributes = $itemAttributes->merge(['data-value' => $value]);
    }

    if ($disabled) {
        $itemAttributes = $itemAttributes
            ->merge([
                'data-disabled' => true,
                'aria-disabled' => 'true',
            ]);
    }
@endphp

<div {{ $itemAttributes }}>
    <span class="min-w-0 flex-1 truncate" data-select-item-label>{{ $slot }}</span>
    <svg
        class="pointer-events-none absolute right-2 top-1/2 size-4 -translate-y-1/2 text-zinc-900 opacity-0 dark:text-zinc-50"
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        stroke-width="2"
        stroke-linecap="round"
        stroke-linejoin="round"
        aria-hidden="true"
        data-select-item-check
    >
        <path d="M20 6 9 17l-5-5" />
    </svg>
</div>

@aware([
    'size' => null,
])

@php
    $labelClasses = collect([
        'select__label',
        'px-2 py-1.5 text-xs font-medium text-zinc-500 dark:text-zinc-400',
    ])->implode(' ');
@endphp

<div
    {{ $attributes->class($labelClasses)->merge([
        'role' => 'presentation',
        'data-select-label' => true,
    ]) }}
>
    {{ $slot }}
</div>

@aware([
    'size' => null,
    'invalid' => false,
    'disabled' => false,
    'selectId' => null,
    'listboxId' => null,
])

@php
    use Ivanfuhr\BladexComponents\Support\Interaction\InteractionStateAttributes;
    use Ivanfuhr\BladexComponents\Support\Interaction\InteractionStateClassMap;
    use Ivanfuhr\BladexComponents\Support\Typography\TypographyClassMap;

    $typography = app(TypographyClassMap::class);
    $interactionState = app(InteractionStateAttributes::class);
    $interactionClasses = app(InteractionStateClassMap::class)->classes(includeReadOnly: true);

    $triggerClasses = collect([
        'select__trigger',
        'flex w-full min-w-0 items-center justify-between gap-2 rounded-md border border-zinc-200 bg-white px-3 py-1 shadow-sm transition-colors',
        $typography->inputControlClasses($size),
        'text-left',
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-zinc-950/10 focus-visible:ring-offset-0',
        $interactionClasses,
        'dark:border-zinc-800 dark:bg-zinc-950',
        'dark:focus-visible:ring-zinc-300/20',
        'aria-expanded:border-zinc-300 aria-expanded:ring-2 aria-expanded:ring-zinc-950/10',
        'dark:aria-expanded:border-zinc-600 dark:aria-expanded:ring-zinc-300/20',
        'aria-invalid:border-red-500 aria-invalid:text-red-950',
        'aria-invalid:focus-visible:ring-red-500/20',
        'dark:aria-invalid:border-red-500 dark:aria-invalid:text-red-50',
        $size === 'sm' ? 'h-8 px-2.5' : 'h-9',
        $invalid ? 'border-red-500 focus-visible:ring-red-500/20 dark:border-red-500' : null,
        'disabled:cursor-not-allowed disabled:opacity-50',
        'aria-disabled:cursor-not-allowed aria-disabled:opacity-50',
        'group',
    ])->filter()->implode(' ');

    $triggerAttributes = $interactionState->apply(
        $attributes
            ->class($triggerClasses)
            ->merge([
                'type' => 'button',
                'aria-haspopup' => 'listbox',
                'aria-expanded' => 'false',
            ]),
        ['nativeDisabled' => true],
    );

    if ($invalid) {
        $triggerAttributes = $triggerAttributes->merge(['aria-invalid' => 'true']);
    }

    if ($disabled) {
        $triggerAttributes = $triggerAttributes->merge(['disabled' => true]);
    }

    if (filled($selectId)) {
        $triggerAttributes = $triggerAttributes->merge(['id' => $selectId.'-trigger']);
    }

    if (filled($listboxId)) {
        $triggerAttributes = $triggerAttributes->merge(['aria-controls' => $listboxId]);
    }

    $chevronClasses = $size === 'sm' ? 'size-3.5 shrink-0 opacity-50' : 'size-4 shrink-0 opacity-50';
@endphp

<button {{ $triggerAttributes }} data-select-trigger>
    <span class="select__trigger-inner flex min-w-0 flex-1 items-center gap-2">
        {{ $slot }}
    </span>
    <svg
        class="{{ $chevronClasses }} text-zinc-500 transition-transform duration-200 group-aria-expanded:rotate-180 dark:text-zinc-400"
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        stroke-width="2"
        stroke-linecap="round"
        stroke-linejoin="round"
        aria-hidden="true"
        data-select-chevron
    >
        <path d="m6 9 6 6 6-6" />
    </svg>
</button>

@aware([
    'placeholder' => null,
    'size' => null,
])

@props([
    'placeholder' => null,
])

@php
    $resolvedPlaceholder = filled($placeholder) ? $placeholder : null;

    $valueClasses = collect([
        'select__value',
        'block min-w-0 flex-1 truncate text-sm leading-5',
        'text-zinc-950 dark:text-zinc-50',
        'data-placeholder:text-zinc-500 dark:data-placeholder:text-zinc-400',
    ])->implode(' ');
@endphp

<span
    {{ $attributes->class($valueClasses)->merge([
        'data-select-value' => true,
        'data-placeholder' => $resolvedPlaceholder !== null ? 'true' : null,
    ]) }}
>
    @if ($slot->isEmpty())
        {{ $resolvedPlaceholder }}
    @else
        {{ $slot }}
    @endif
</span>
